<script setup lang="ts">
import { computed,reactive,ref } from "vue"; import {useRoute,useRouter} from "vue-router"; import {Mail} from "lucide-vue-next";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import Tabs from "@/components/zs/Tabs.vue"; import ScoreBadge from "@/components/crm/ScoreBadge.vue"; import ActivityTimeline from "@/components/crm/ActivityTimeline.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import ZButton from "@/components/zs/ZButton.vue"; import Field from "@/components/zs/Field.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue";
import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData,useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import {showToast} from "@/composables/useToast"; import {formatMoney,parseMoneyInput,toMoneyInput} from "@/lib/money"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("Lead Workspace","Qualification, scoring, activity and conversion in one workspace.");const route=useRoute(),router=useRouter(),data=useCrmData(),tab=ref("Overview"),editOpen=ref(false),conversionOpen=ref(false),activityOpen=ref(false),id=computed(()=>String(route.params.id));const state=useAsyncData(()=>crmRepository.lead(data.activeCompanyId.value,id.value),{watch:[data.activeCompanyId,id]});const lead=computed(()=>state.data.value),activities=computed(()=>(data.activities.data.value??[]).filter((item)=>item.leadId===id.value));
const editForm=reactive({first_name:"",last_name:"",company_name:"",job_title:"",email:"",phone:"",website:"",source:"",owner_id:"",estimated_value:"0.00",currency:"PKR",expected_timeframe:"",interest:"",notes:"",qualification_notes:""});function prepareEdit(){if(!lead.value)return;Object.assign(editForm,{first_name:lead.value.firstName,last_name:lead.value.lastName,company_name:lead.value.company,job_title:lead.value.title,email:lead.value.email,phone:lead.value.phone,website:lead.value.website,source:lead.value.source,owner_id:lead.value.ownerId?String(lead.value.ownerId):"",estimated_value:toMoneyInput(lead.value.value),currency:lead.value.currency,expected_timeframe:lead.value.expectedTimeframe??"",interest:lead.value.interest??"",notes:lead.value.notes,qualification_notes:lead.value.qualificationNotes??""});editOpen.value=true;}const editMutation=useMutation(()=>crmRepository.updateLead(data.activeCompanyId.value,id.value,{...editForm,owner_id:editForm.owner_id?Number(editForm.owner_id):null,estimated_value:parseMoneyInput(editForm.estimated_value)??-1,status:lead.value?.status??"NEW",expected_timeframe:editForm.expected_timeframe||null}));async function saveEdit(){const saved=await editMutation.run();if(!saved)return;editOpen.value=false;await Promise.all([state.refresh(),data.leads.refresh()]);showToast("Lead saved",saved.name,"success");}
const transitionMutation=useMutation((status:string)=>crmRepository.transitionLead(data.activeCompanyId.value,id.value,status));const scoreMutation=useMutation(()=>crmRepository.recalculateScore(data.activeCompanyId.value,"lead",id.value));async function transition(status:string){const saved=await transitionMutation.run(status);if(!saved)return;await Promise.all([state.refresh(),data.leads.refresh(),data.dashboard.refresh()]);showToast("Lead status updated",saved.status,"success");}async function recalculate(){const saved=await scoreMutation.run();if(!saved)return;await Promise.all([state.refresh(),data.leads.refresh()]);showToast("Score recalculated","Active scoring rules were applied.","success");}
const conversion=reactive({create_account:true,create_contact:true,create_deal:true,account_id:"",contact_id:"",pipeline_id:"",pipeline_stage_id:"",deal_title:""});const conversionStages=computed(()=>data.pipelines.data.value?.find((item)=>item.id===conversion.pipeline_id)?.stages??[]);function prepareConversion(){const pipeline=data.pipelines.data.value?.find((item)=>item.isDefault)??data.pipelines.data.value?.[0];Object.assign(conversion,{create_account:true,create_contact:true,create_deal:true,account_id:"",contact_id:"",pipeline_id:pipeline?.id??"",pipeline_stage_id:pipeline?.stages[0]?.id??"",deal_title:`${lead.value?.company||lead.value?.name||"Lead"} opportunity`});conversionOpen.value=true;}const convertMutation=useMutation(()=>crmRepository.convertLead(data.activeCompanyId.value,id.value,{...conversion,account_id:conversion.account_id||null,contact_id:conversion.contact_id||null,pipeline_id:conversion.create_deal?conversion.pipeline_id:null,pipeline_stage_id:conversion.create_deal?conversion.pipeline_stage_id:null,deal_title:conversion.deal_title||null}));async function convert(){const saved=await convertMutation.run();if(!saved)return;conversionOpen.value=false;await data.refresh();await state.refresh();showToast("Lead converted","The original lead is preserved and linked to its resulting records.","success");}
const activity=reactive({type:"CALL",subject:"",description:"",due_at:"",priority:"MEDIUM"});const activityMutation=useMutation(()=>crmRepository.createActivity(data.activeCompanyId.value,{...activity,related_type:"lead",related_id:id.value,status:"PENDING"}));async function logActivity(){const saved=await activityMutation.run();if(!saved)return;activityOpen.value=false;await data.activities.refresh();showToast("Activity saved",saved.subject,"success");}
</script>
<template><AppShell><AsyncSection :loading="state.loading.value" :error="state.error.value" @retry="state.refresh"><template v-if="lead"><PageHeader :title="lead.name" :description="`${lead.title||'Lead'} at ${lead.company||'Unlinked company'}`"><template #actions><StatusBadge :status="lead.status"/><ZButton variant="outline" :disabled="lead.status==='CONVERTED'" @click="prepareEdit">Edit</ZButton><ZButton variant="outline" :disabled="scoreMutation.saving.value" @click="recalculate">Recalculate score</ZButton><ZButton variant="outline" @click="activityOpen=true">Log activity</ZButton><ZButton v-if="lead.status==='QUALIFIED'" @click="prepareConversion">Convert lead</ZButton><ZButton variant="outline" @click="router.push({path:'/outreach/compose',query:{lead:lead.id}})"><Mail class="size-3.5"/>Outreach</ZButton></template></PageHeader><div class="mb-3 grid gap-3 sm:grid-cols-3"><div class="panel p-4"><p class="label-caps">Status</p><select :value="lead.status" class="field mt-2" :disabled="lead.status==='CONVERTED'||transitionMutation.saving.value" @change="transition(($event.target as HTMLSelectElement).value)"><option v-for="value in ['NEW','CONTACTED','QUALIFIED','UNQUALIFIED','LOST']" :key="value">{{value}}</option></select><ValidationMessage :message="transitionMutation.error.value?.message"/></div><div class="panel p-4"><p class="label-caps">Estimated value</p><p class="num mt-2 text-xl font-semibold text-content">{{formatMoney(lead.value,lead.currency)}}</p></div><div class="panel flex items-center justify-between p-4"><div><p class="label-caps">Lead score</p><p class="num mt-2 text-2xl font-semibold text-content">{{lead.score.total}}</p></div><ScoreBadge :score="lead.score.total"/></div></div><Panel><Tabs v-model="tab" :items="['Overview','Activities','Scoring','Notes']"/><div v-if="tab==='Overview'" class="grid gap-5 p-5 sm:grid-cols-2"><div v-for="[key,value] in Object.entries({Email:lead.email,Phone:lead.phone,Website:lead.website,Source:lead.source,Status:lead.status,Owner:lead.owner||'Unassigned','Expected timeframe':lead.expectedTimeframe||'—',Interest:lead.interest||'—'})" :key="key"><p class="label-caps">{{key}}</p><p class="mt-1 text-sm text-content">{{value}}</p></div><div v-if="lead.status==='CONVERTED'" class="sm:col-span-2 rounded-md border border-success/30 bg-success/10 p-4"><p class="text-sm font-semibold text-success">Conversion complete</p><div class="mt-3 flex flex-wrap gap-2"><ZButton v-if="lead.convertedAccountId" variant="outline" @click="router.push(`/crm/companies/${lead.convertedAccountId}`)">Open account</ZButton><ZButton v-if="lead.convertedContactId" variant="outline" @click="router.push(`/crm/contacts/${lead.convertedContactId}`)">Open contact</ZButton><ZButton v-if="lead.convertedDealId" variant="outline" @click="router.push(`/crm/deals/${lead.convertedDealId}`)">Open deal</ZButton></div></div></div><div v-else-if="tab==='Activities'" class="p-4"><ActivityTimeline :items="activities"/></div><div v-else-if="tab==='Scoring'" class="p-5"><div v-for="event in lead.scoreEvents??[]" :key="event.id" class="flex items-center justify-between border-b border-line py-3"><div><p class="text-sm font-medium text-content">{{event.reason}}</p><p class="text-xs text-content-muted">{{event.calculatedAt}}</p></div><span class="num text-sm">{{event.points>0?'+':''}}{{event.points}}</span></div><p v-if="!lead.scoreEvents?.length" class="text-sm text-content-muted">Recalculate to record the current scoring breakdown.</p></div><div v-else class="p-5 text-sm text-content-secondary">{{lead.notes||'No notes recorded.'}}</div></Panel></template></AsyncSection>
<SidePanel :open="editOpen" title="Edit lead" @close="editOpen=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="saveEdit"><Field v-model="editForm.first_name" label="First name" required/><Field v-model="editForm.last_name" label="Last name"/><Field v-model="editForm.company_name" label="Company"/><Field v-model="editForm.job_title" label="Job title"/><Field v-model="editForm.email" label="Email" type="email"/><Field v-model="editForm.phone" label="Phone"/><Field v-model="editForm.website" label="Website"/><Field v-model="editForm.estimated_value" label="Estimated value"/><label><span class="label-caps">Owner</span><select v-model="editForm.owner_id" class="field mt-1.5"><option value="">Unassigned</option><option v-for="owner in data.owners.data.value??[]" :key="owner.id" :value="owner.id">{{owner.name}}</option></select></label><Field v-model="editForm.expected_timeframe" label="Expected timeframe" type="date"/><label class="sm:col-span-2"><span class="label-caps">Notes</span><textarea v-model="editForm.notes" class="field mt-1.5 min-h-20"/></label><ValidationMessage class="sm:col-span-2" :message="editMutation.error.value?.message"/><ZButton type="submit">Save lead</ZButton></form></SidePanel>
<SidePanel :open="conversionOpen" title="Convert qualified lead" description="Create or link CRM records in one idempotent conversion." @close="conversionOpen=false"><form class="grid gap-4" @submit.prevent="convert"><label class="flex items-center gap-2 text-sm"><input v-model="conversion.create_account" type="checkbox"/>Create a new account</label><label v-if="!conversion.create_account"><span class="label-caps">Existing account</span><select v-model="conversion.account_id" class="field mt-1.5"><option value="">Select account</option><option v-for="account in data.companies.data.value??[]" :key="account.id" :value="account.id">{{account.name}}</option></select></label><label class="flex items-center gap-2 text-sm"><input v-model="conversion.create_contact" type="checkbox"/>Create a new contact</label><label v-if="!conversion.create_contact"><span class="label-caps">Existing contact</span><select v-model="conversion.contact_id" class="field mt-1.5"><option value="">Select contact</option><option v-for="contact in data.contacts.data.value??[]" :key="contact.id" :value="contact.id">{{contact.name}}</option></select></label><label class="flex items-center gap-2 text-sm"><input v-model="conversion.create_deal" type="checkbox"/>Create a deal</label><template v-if="conversion.create_deal"><Field v-model="conversion.deal_title" label="Deal title"/><label><span class="label-caps">Pipeline</span><select v-model="conversion.pipeline_id" class="field mt-1.5" @change="conversion.pipeline_stage_id=conversionStages[0]?.id??''"><option v-for="pipeline in data.pipelines.data.value??[]" :key="pipeline.id" :value="pipeline.id">{{pipeline.name}}</option></select></label><label><span class="label-caps">Initial stage</span><select v-model="conversion.pipeline_stage_id" class="field mt-1.5"><option v-for="stage in conversionStages" :key="stage.id" :value="stage.id">{{stage.name}}</option></select></label></template><ValidationMessage :message="convertMutation.error.value?.message"/><ZButton type="submit" :disabled="convertMutation.saving.value">Convert lead</ZButton></form></SidePanel>
<SidePanel :open="activityOpen" title="Log lead activity" @close="activityOpen=false"><form class="grid gap-4" @submit.prevent="logActivity"><label><span class="label-caps">Type</span><select v-model="activity.type" class="field mt-1.5"><option>CALL</option><option>MEETING</option><option>EMAIL</option><option>TASK</option><option>NOTE</option></select></label><Field v-model="activity.subject" label="Subject" required/><Field v-model="activity.due_at" label="Due at" type="datetime-local"/><label><span class="label-caps">Description</span><textarea v-model="activity.description" class="field mt-1.5 min-h-20"/></label><ValidationMessage :message="activityMutation.error.value?.message"/><ZButton type="submit">Save activity</ZButton></form></SidePanel></AppShell></template>
